import subprocess, re, itertools, sys, os
OPP=['stone','paper','vampire','snake','g2-clear']
NEED={'stone':75,'paper':75,'vampire':75,'snake':33,'g2-clear':33}
def test(path, rounds=100):
    res={}
    for o in OPP:
        out=subprocess.run(['pmars','-b','-r',str(rounds),'-f',path,f'/app/warriors/{o}.red'],capture_output=True,text=True)
        m=re.search(r'Results:\s+(\d+)\s+(\d+)\s+(\d+)', out.stdout)
        if not m: return None
        res[o]=tuple(map(int,m.groups()))
    return res
def margin(res, rounds=100):
    return min(res[o][0]*100.0/rounds-NEED[o] for o in OPP)

def build(dec, skip, gap, b2, nmov):
    # code layout: dbomb, bptr, bomb, clear, [movs], djn
    movs = "\n".join(["        mov.i   *bptr, >gate" if (i%2==0 or b2=='spl') else f"        mov.i   dbomb, >gate" for i in range(nmov)])
    return f""";redcode-94
;name Sweeper
;author me
;assert CORESIZE == 8000 && MAXCYCLES == 80000
dec     equ     {dec}
gate    equ     clear-{gap}
        org     bomb
dbomb   dat.f   #0, #{skip}
bptr    dat.f   bomb, 9
bomb    spl.b   #dec, {skip}
clear
{movs}
        djn.f   clear, }}bomb
        end
"""
best=[]
for dec in (2700, 2667, 1300, 4000, 800):
  for skip in (11, 15):
    for gap in (4, 5, 6, 8):
      for b2 in ('spl','dat'):
        for nmov in (2,3):
          src=build(dec,skip,gap,b2,nmov)
          open('/tmp/g/w.red','w').write(src)
          r=test('/tmp/g/w.red',100)
          if r is None:
              continue
          m=margin(r)
          best.append((m,(dec,skip,gap,b2,nmov),{o:r[o][0] for o in OPP}))
best.sort(reverse=True)
for b in best[:12]: print(b)
