import subprocess, re, itertools, sys
OPP=['stone','paper','vampire','snake','g2-clear']
NEED={'stone':75,'paper':75,'vampire':75,'snake':33,'g2-clear':33}
def test(path, rounds=100):
    res={}
    for o in OPP:
        out=subprocess.run(['pmars','-b','-r',str(rounds),'-f',path,f'/app/warriors/{o}.red'],capture_output=True,text=True)
        m=re.search(r'Results:\s+(\d+)\s+(\d+)\s+(\d+)', out.stdout)
        if not m: return None
        res[o]=tuple(map(int,m.groups()))
    return res
def margin(res, rounds=100):
    return min(res[o][0]*100.0/rounds-NEED[o] for o in OPP)

def build(dec=2700, nmov=2, b2='dat', stream=None, pump=True, pad=2):
    # layout indices
    lines=[]   # (label, text)
    L={}
    def add(lab, txt):
        L[lab]=len(lines); lines.append(txt)
    add('gate','dat.f 0, 0')
    add('dbomb','dat.f #0, #SKIP')
    add('bptr','dat.f BOMBOFF, 9')
    add('bomb','spl.b #%d, SKIP'%dec)
    clear=len(lines)
    for i in range(nmov):
        if i%2==0 or b2=='spl':
            add('m%d'%i,'mov.i *bptr, >gate')
        else:
            add('m%d'%i,'mov.i dbomb, >gate')
    add('djn','djn.f CLEAR, }bomb')
    if stream is not None:
        add('stream','djn.f STREAM, <%d'%stream)
    start_lab='bomb' if pump else 'clear'
    if stream is not None:
        add('boot','spl.a STREAMREL, 0')
        add('boot2','jmp STARTREL, 0')
        org='boot'
    else:
        org=start_lab
    n=len(lines)
    skip=n+pad
    out=[]
    for i,t in enumerate(lines):
        t=t.replace('SKIP',str(skip))
        t=t.replace('BOMBOFF',str(L['bomb']-L['bptr']))
        t=t.replace('CLEAR',str(clear-L['djn']))
        if 'STREAMREL' in t: t=t.replace('STREAMREL',str(L['stream']-L['boot']))
        if 'STARTREL' in t: t=t.replace('STARTREL',str(L[start_lab]-L['boot2']))
        if t.startswith('djn.f STREAM'): t=t.replace('STREAM','0')
        out.append('        '+t)
    src=';redcode-94\n;name Sweeper\n;author me\n;assert CORESIZE == 8000 && MAXCYCLES == 80000\n'
    src+='        org     %d\n'%0  # placeholder
    src='\n'.join([';redcode-94',';name Sweeper',';author me',';assert CORESIZE == 8000 && MAXCYCLES == 80000'])+'\n'
    src+='start\n'
    # use ORG via 'end' statement with offset label: emit labels
    lab_lines=[]
    for i,t in enumerate(out):
        lab_lines.append('L%d      %s'%(i,t.strip()))
    src='\n'.join([';redcode-94',';name Sweeper',';author me',';assert CORESIZE == 8000 && MAXCYCLES == 80000'])+'\n'
    src+='\n'.join(lab_lines)+'\n'
    src+='        end     L%d\n'%L[org]
    # fix relative refs to labels
    src=src.replace('>gate','>L%d'%L['gate']).replace('*bptr','*L%d'%L['bptr']).replace('dbomb, ','L%d, '%L['dbomb']).replace('}bomb','}L%d'%L['bomb'])
    return src

if __name__=='__main__':
    print(build(stream=2000))
EOF
